import re
from flask import Flask, request, jsonify

app = Flask(__name__)

def safe_eval(expression):
    # Remove any characters that are not digits, decimal points, parentheses, or basic operators
    # This prevents code injection
    allowed_chars = re.compile(r'[^0-9+\-*/(). %]')
    if allowed_chars.sub('', expression) != expression:
        return None

    # Replace ^ with ** for exponentiation if needed
    expression = expression.replace('^', '**')

    try:
        result = eval(expression, {"__builtins__": None}, {})
        # Ensure result is a number
        if isinstance(result, (int, float)):
            return str(result)
        else:
            return None
    except:
        return None

@app.route('/calculator', methods=['POST'])
def calculate():
    data = request.get_json(silent=True)
    if not data or 'expression' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    expression = data['expression']
    if not isinstance(expression, str):
        return jsonify({'error': 'Invalid input'}), 400

    result = safe_eval(expression)
    if result is None:
        return jsonify({'error': 'Invalid input'}), 400

    return jsonify({'result': result}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
